// Reset per-run counters and start the pagination loop at page 1.
const s = $getWorkflowStaticData('global');
s.written = 0;
s.skipped = 0;
s.pageWritten = 0;
s.pageSkipped = 0;
s.pageFailedProfiles = 0;
s.failedPages = [];
s.failedProfiles = [];

const cfg = $('Config').first().json;
console.log('=== EmBRACE lead-gen: RUN START ===');
console.log(`County: ${cfg.county_name} (code ${cfg.county_code})  |  Size: ${cfg.size_category}  |  test_mode: ${cfg.test_mode}`);
console.log(`Employees ${cfg.employees_from}-${cfg.employees_to}  |  Revenue ${cfg.revenue_from}-${cfg.revenue_to} EUR`);
if (cfg.test_mode === true) console.log('test_mode is ON: pagination stops after page 2.');

return [{ json: { page: 1 } }];

// ---------------------------------------------------------------------------
// Tunable: ScrapingBee renders JavaScript by default (5 credits/call). The
// companywall search results are server-rendered, so we ask for raw HTML
// (1 credit/call) and only fall back to render_js=true on an unexpectedly
// empty page 1 -- see the "Retry Page 1 With JS" node.
// If every page comes back empty, flip this to true.
// ---------------------------------------------------------------------------
const RENDER_JS = false;

const cfg = $('Config').first().json;
const page = Number($input.first().json.page) || 1;

const search_url = 'https://www.companywall.hr/pretraga?' + [
  'cr=EUR',
  `r=${cfg.county_code}`,
  'sbjact=t',
  'bly=2025',
  'dsm[0].Code=411',
  `dsm[0].From=${cfg.revenue_from}`,
  `dsm[0].To=${cfg.revenue_to}`,
  'dsm[1].Code=2138',
  `dsm[1].From=${cfg.employees_from}`,
  `dsm[1].To=${cfg.employees_to}`,
  'dsm[-1].Code=0',
  'dsm[-1].From=0',
  'dsm[-1].To=0',
  'xpnd=true',
  `p=${page}`,
].join('&');

console.log(`--- Page ${page} -> ${search_url}`);

return [{ json: { page, search_url, render_js: RENDER_JS } }];

// Turn the ScrapingBee response into { page, failed, count, companies }.
// A failed page is logged and skipped; a genuinely empty page ends the run.
const cfg = $('Config').first().json;
const page = Number($('Build Search URL').first().json.page) || 1;
const raw = $input.first().json;
const s = $getWorkflowStaticData('global');

// Per-page counters (the run totals keep accumulating).
s.pageWritten = 0;
s.pageSkipped = 0;
s.pageFailedProfiles = 0;

let companies = null;
let failed = false;
let reason = '';

if (raw && raw.error !== undefined) {
  failed = true;
  reason = typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 300);
} else if (raw && Array.isArray(raw.companies)) {
  companies = raw.companies;
} else {
  failed = true;
  reason = 'ScrapingBee response had no "companies" array: ' + JSON.stringify(raw).slice(0, 300);
}

companies = companies || [];

if (failed) {
  s.failedPages.push({ county: cfg.county_name, size_category: cfg.size_category, page, reason });
  console.log(`!! PAGE FAILED after retries -- ${cfg.county_name} page ${page}: ${reason}`);
  console.log(`   Skipping page ${page} and continuing with page ${page + 1}.`);
} else {
  console.log(`Page ${page}: ${companies.length} companies in search results.`);
}

return [{ json: { page, failed, reason, count: companies.length, companies } }];

// One n8n item per company. Everything stays raw text -- employees and revenue
// keep their Croatian formatting ("1.568.788,47", "3") on purpose; number
// cleanup happens manually, outside this workflow.
const src = $input.first().json;

const str = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) v = v.find((x) => x !== null && x !== undefined && String(x).trim() !== '') ?? '';
  return String(v).replace(/\s+/g, ' ').trim();
};

return (src.companies || [])
  .filter((c) => c && (c.name || c.profile_url))
  .map((c) => ({
    json: {
      name: str(c.name),
      profile_url_raw: str(c.profile_url),
      status: str(c.status),
      oib: str(c.oib),
      employees: str(c.employees),
      revenue: str(c.revenue),
      page: src.page,
    },
  }));

// Extend the company item (search-page fields) with the profile-page fields.
// No Merge node: this is one sequential item, so we just add keys to it.
const base = $('Loop Over Companies').first().json;
const raw = $input.first().json;
const s = $getWorkflowStaticData('global');

const str = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) v = v.find((x) => x !== null && x !== undefined && String(x).trim() !== '') ?? '';
  return String(v).replace(/\s+/g, ' ').trim();
};

const LABELS = {
  owner_director: ['Vlasnik', 'Vlasnici', 'Direktor', 'Direktori', 'Odgovorna osoba', 'Član uprave'],
  email: ['E-mail', 'E-pošta', 'Email', 'Mail'],
  founding_date: ['Datum osnivanja', 'Datum upisa', 'Osnovan', 'Osnovana'],
  nkd_code: ['NKD 2007', 'NKD', 'Šifra djelatnosti', 'Pretežita djelatnost', 'Djelatnost'],
  mbs: ['MBS', 'Matični broj subjekta', 'Matični broj'],
};

const ALL_LABELS = new Set(Object.values(LABELS).flat().map((l) => l.toLowerCase()));

const fields = { owner_director: '', email: '', founding_date: '', nkd_code: '', mbs: '' };

const failed = !raw || typeof raw !== 'object' || raw.error !== undefined;
const reason = failed
  ? (raw && raw.error !== undefined
      ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 300))
      : 'empty ScrapingBee response')
  : '';

if (!failed) {
  for (const key of Object.keys(fields)) fields[key] = str(raw[key]);

  // Safety net: the XPath rules key off exact label text, which can drift. Scan
  // the page text for the same labels and fill in whatever came back empty.
  const pageText = typeof raw.page_text === 'string'
    ? raw.page_text
    : Array.isArray(raw.page_text) ? raw.page_text.join('\n') : '';
  const lines = pageText.split('\n').map((l) => l.replace(/\s+/g, ' ').trim()).filter(Boolean);
  const esc = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const fromLabels = (labels) => {
    for (const label of labels) {
      const re = new RegExp('^' + esc(label) + '\\s*:?\\s*(.*)$', 'i');
      for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(re);
        if (!m) continue;
        const inline = m[1].trim();
        const candidate = inline || (lines[i + 1] || '');
        if (candidate && candidate.length <= 300 && !ALL_LABELS.has(candidate.toLowerCase().replace(/:$/, ''))) {
          return candidate;
        }
      }
    }
    return '';
  };

  for (const key of Object.keys(fields)) {
    if (!fields[key]) fields[key] = fromLabels(LABELS[key]);
    if (fields[key].length > 300) fields[key] = fields[key].slice(0, 300);
  }

  if (!fields.email) {
    const m = pageText.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
    if (m) fields.email = m[0];
  }
} else {
  s.failedProfiles.push({ name: base.name, oib: base.oib, url: base.profile_url, page: base.page, reason });
  s.pageFailedProfiles = (s.pageFailedProfiles || 0) + 1;
  console.log(`!! PROFILE FETCH FAILED for ${base.name} (OIB ${base.oib}): ${reason}`);
  console.log('   Writing the row with search-page data only; profile columns left blank.');
}

return [{ json: { ...base, ...fields, profile_failed: failed } }];

const c = $('Add Profile Fields').first().json;
const s = $getWorkflowStaticData('global');
s.written = (s.written || 0) + 1;
s.pageWritten = (s.pageWritten || 0) + 1;
console.log(`Written: ${c.name} (OIB ${c.oib})`);
return $input.all();

const c = $('Add Profile Fields').first().json;
const s = $getWorkflowStaticData('global');
s.skipped = (s.skipped || 0) + 1;
s.pageSkipped = (s.pageSkipped || 0) + 1;
console.log(`Skipped duplicate: ${c.oib} (${c.name})`);
return $input.all();

// Page finished (or was skipped after a failed fetch). Log it, then decide
// whether to fetch another page.
const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');
const page = Number($('Build Search URL').first().json.page) || 1;

console.log(
  `Page ${page} done: ${s.pageWritten || 0} companies written, ` +
  `${s.pageSkipped || 0} duplicates skipped, ${s.pageFailedProfiles || 0} profile fetches failed ` +
  `(run totals: ${s.written || 0} written / ${s.skipped || 0} skipped)`
);

const nextPage = page + 1;
const stop = cfg.test_mode === true && nextPage > 2;
if (stop) console.log('test_mode is ON and pages 1-2 are done -- stopping here.');

return [{ json: { page: nextPage, stop } }];

const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');
const failedPages = s.failedPages || [];
const failedProfiles = s.failedProfiles || [];

console.log('=== EmBRACE lead-gen: RUN COMPLETE ===');
console.log(`County: ${cfg.county_name} (code ${cfg.county_code})  |  Size: ${cfg.size_category}`);
console.log(`Rows written: ${s.written || 0}  |  Duplicates skipped: ${s.skipped || 0}`);
console.log(`Pages skipped after failed retries: ${failedPages.length}`);
if (failedPages.length) console.log(JSON.stringify(failedPages, null, 2));
console.log(`Profiles that failed (row written from search data only): ${failedProfiles.length}`);
if (failedProfiles.length) console.log(JSON.stringify(failedProfiles, null, 2));

return [{
  json: {
    county: cfg.county_name,
    county_code: cfg.county_code,
    size_category: cfg.size_category,
    test_mode: cfg.test_mode,
    rows_written: s.written || 0,
    duplicates_skipped: s.skipped || 0,
    failed_pages: failedPages,
    failed_profiles: failedProfiles,
  },
}];
